// Frozen 16-state classical simulation of a reversible EC relation phase oracle.
use std::f64::consts::PI;
const P:i64=1009; const N:usize=16;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]enum Pt{O,A(i64,i64)}
fn m(x:i64)->i64{x.rem_euclid(P)}
fn inv(x:i64)->i64{let(mut a,mut b,mut u,mut v)=(m(x),P,1,0);while b!=0{let q=a/b;(a,b)=(b,a-q*b);(u,v)=(v,u-q*v)}assert_eq!(a,1);m(u)}
fn neg(p:Pt)->Pt{match p{Pt::O=>p,Pt::A(x,y)=>Pt::A(x,m(-y))}}
fn add(a:Pt,b:Pt)->Pt{match(a,b){(Pt::O,x)|(x,Pt::O)=>x,(Pt::A(x,y),Pt::A(u,v))=>{if x==u&&m(y+v)==0{return Pt::O}let s=if x==u{m((3*x*x+1)*inv(2*y))}else{m((v-y)*inv(u-x))};let xx=m(s*s-x-u);Pt::A(xx,m(s*(x-xx)-y))}}}
fn encode(p:Pt)->u32{match p{Pt::O=>0,Pt::A(x,y)=>1+x as u32+P as u32*y as u32}}
fn predicate(i:usize)->bool{let t1=[Pt::A(4,456),Pt::A(10,32),Pt::A(29,35)];let t2=[Pt::A(5,12),Pt::A(10,32),Pt::A(25,23)];let t=if i<8{t1}else{t2};let bits=i%8;let mut out=Pt::O;for j in 0..3{out=add(out,if bits&(1<<j)!=0{neg(t[j])}else{t[j]})}out==Pt::A(0,425)}
fn reversible_phase(i:usize,a:&mut f64)->usize{let mut work=0u32;let mut flag=false;let mark=encode(Pt::A(0,425));work^=encode(signsum(i));flag^=work==mark;if flag{*a = -*a}flag^=work==mark;work^=encode(signsum(i));assert_eq!(work,0);assert!(!flag);2}
fn signsum(i:usize)->Pt{let t1=[Pt::A(4,456),Pt::A(10,32),Pt::A(29,35)];let t2=[Pt::A(5,12),Pt::A(10,32),Pt::A(25,23)];let t=if i<8{t1}else{t2};let bits=i%8;let mut out=Pt::O;for j in 0..3{out=add(out,if bits&(1<<j)!=0{neg(t[j])}else{t[j]})}out}
fn classical(k:usize,marked:usize)->f64{let mut miss=1.0;for i in 0..k{miss*=(N-marked-i) as f64/(N-i) as f64}1.0-miss}
fn main(){let mut mark=[false;N];for i in 0..N{mark[i]=predicate(i);assert_eq!(mark[i],signsum(i)==Pt::A(0,425))}let masks:Vec<_>=(0..N).filter(|&i|mark[i]).collect();assert_eq!(masks,vec![5,14]);println!("input curve=F1009:y2=x3+x+14 candidates=16 marked={:?} truth_table={:?} truth_ec_checks=16",masks,mark.map(|x|if x{1}else{0}));let theta=((masks.len() as f64/N as f64).sqrt()).asin();let mut amp=[1.0/(N as f64).sqrt();N];for iter in 0..=5{let prob:f64=(0..N).filter(|&i|mark[i]).map(|i|amp[i]*amp[i]).sum();let expected=((2*iter+1) as f64*theta).sin().powi(2);assert!((prob-expected).abs()<1e-12);let norm:f64=amp.iter().map(|x|x*x).sum();assert!((norm-1.0).abs()<1e-12);println!("iteration={} grover_success={:.12} formula={:.12} classical_without_replacement={:.12} logical_phase_oracles={} coherent_predicate_compute_uncompute={} simulator_branch_ec_evals={} post_measure_verify=1",iter,prob,expected,classical(iter,masks.len()),iter,2*iter,32*iter);if iter==5{break}let mut evals=0;for i in 0..N{let old=amp[i];evals+=reversible_phase(i,&mut amp[i]);assert_eq!(amp[i],if mark[i]{-old}else{old})}assert_eq!(evals,32);let mean=amp.iter().sum::<f64>()/N as f64;for x in &mut amp{*x=2.0*mean-*x}}assert!((PI-3.141592653589793).abs()<1e-15);println!("claim_boundary=classical_statevector_simulation no_quantum_circuit_gate_count=true no_hardware=true oracle_lookup_free_assumption=false");}
